eq(base.strides,{32,8},"hfft/int64/(3, 4)/np.flip(base,1)/n3/axis0/None/outNone/False: source state: strides")
eq(base.dtype,"int64","hfft/int64/(3, 4)/np.flip(base,1)/n3/axis0/None/outNone/False: source state: dtype")
cases=cases+1
end
