assert(ok==true,"ihfft/int16/(3, 4)/np.flip(base,1)/n2/axis1/backward/outNone/False: acceptance"..": "..tostring(result))
eq(result:tolist(),{{np.complex(8.5,-0.0),np.complex(-0.5,-0.0)},{np.complex(4.5,-0.0),np.complex(-0.5,-0.0)},{np.complex(0.5,-0.0),np.complex(-0.5,-0.0)}},"ihfft/int16/(3, 4)/np.flip(base,1)/n2/axis1/backward/outNone/False: result",2e-12,2e-12)
