eq(base.strides,{8,2},"ihfft/int16/(3, 4)/np.flip(base,1)/n2/axis1/backward/outNone/False: source state: strides")
eq(base.dtype,"int16","ihfft/int16/(3, 4)/np.flip(base,1)/n2/axis1/backward/outNone/False: source state: dtype")
cases=cases+1
end
